def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay keys and values over defaults (mode=fast, level=3) and return resulting values.

    The returned values are ordered by:
    1. 'mode' (default 'fast')
    2. 'level' (default '3')
    3. Any additional keys in the order they first appeared in `keys`.

    Later occurrences of a key overwrite earlier values.
    """
    merged: dict[str, str] = {"mode": "fast", "level": "3"}
    for k, v in zip(keys, values, strict=False):
        merged[k] = v
    return list(merged.values())


def test_settings_empty_uses_defaults() -> None:
    assert settings([], []) == ["fast", "3"]


def test_settings_override_mode() -> None:
    assert settings(["mode"], ["safe"]) == ["safe", "3"]


def test_settings_override_level() -> None:
    assert settings(["level"], ["5"]) == ["fast", "5"]


def test_settings_override_both_defaults() -> None:
    assert settings(["level", "mode"], ["1", "slow"]) == ["slow", "1"]


def test_settings_additional_keys() -> None:
    assert settings(["retries", "timeout"], ["5", "30"]) == ["fast", "3", "5", "30"]


def test_settings_mixed_override_and_additional() -> None:
    assert settings(
        ["timeout", "mode", "retries"],
        ["10", "ultra", "2"],
    ) == ["ultra", "3", "10", "2"]


def test_settings_duplicate_keys_last_wins() -> None:
    assert settings(
        ["mode", "threads", "mode", "threads"],
        ["slow", "4", "turbo", "8"],
    ) == ["turbo", "3", "8"]


def test_settings_duplicate_extra_keys_maintain_first_seen_order() -> None:
    assert settings(
        ["b", "a", "b"],
        ["1", "2", "3"],
    ) == ["fast", "3", "3", "2"]

